function waxPaths(a,b,area){return [a,b].map((s,i)=>`<g>${cell(s,220,435+i*90,650,{thin:true})}<path id="wax-${i}" fill="none" stroke="${INK}" stroke-width="14" stroke-linecap="butt" stroke-linejoin="round"/><path id="wax-fill-${i}" fill="none" stroke="#ecc158" stroke-width="8" stroke-linecap="butt" stroke-linejoin="round"/><path id="end-${i}" d="" stroke="${INK}" stroke-width="2.8"/></g>`).join('')+`<path id="reference" d="" stroke="#77806f" stroke-width="2.2" stroke-dasharray="5 6"/>`;}

function samples(shape,area,n=96){const p=vertices(shape,area),segments=p.map((v,i)=>Math.hypot(v[0]-p[(i+1)%p.length][0],v[1]-p[(i+1)%p.length][1])),total=segments.reduce((a,b)=>a+b,0);return Array.from({length:n+1},(_,k)=>{let d=k*total/n,j=0;while(j<segments.length-1&&d>segments[j])d-=segments[j++];const t=d/segments[j],v=p[j],u=p[(j+1)%p.length];return[v[0]+(u[0]-v[0])*t,v[1]+(u[1]-v[1])*t];});}
